#!/usr/bin/env node

const { spawnSync } = require("child_process");

function getPlatformPkgName(suffix) {
  const rootPkg = require("../package.json").name;
  if (rootPkg.includes("/")) {
    const [scope, name] = rootPkg.split("/");
    return `${scope}/${name}-${suffix}`;
  }
  return `${rootPkg}-${suffix}`;
}

function resolveTarget() {
  const platform = process.platform;
  const arch = process.arch;

  if (platform === "linux" && arch === "x64") {
    return {
      pkg: getPlatformPkgName("linux-x64"),
      bin: "uexcli-linux",
    };
  }
  if (platform === "linux" && arch === "arm64") {
    return {
      pkg: getPlatformPkgName("linux-arm64"),
      bin: "uexcli-linux",
    };
  }
  if (platform === "darwin" && arch === "arm64") {
    return {
      pkg: getPlatformPkgName("darwin-arm64"),
      bin: "uexcli-darwin-arm64",
    };
  }
  if (platform === "win32" && arch === "x64") {
    return {
      pkg: getPlatformPkgName("windows-x64"),
      bin: "uexcli-windows.exe",
    };
  }

  throw new Error(`unsupported platform: ${platform} ${arch}`);
}

function main() {
  const target = resolveTarget();
  const binPath = require.resolve(`${target.pkg}/${target.bin}`);

  const result = spawnSync(binPath, process.argv.slice(2), {
    stdio: "inherit",
  });

  if (result.error) {
    throw result.error;
  }

  process.exit(result.status == null ? 1 : result.status);
}

try {
  main();
} catch (err) {
  console.error(err && err.message ? err.message : err);
  process.exit(1);
}
